function validate(input) {
  const [{ Players = [], Championships = [] }] = input;
  const ids = new Set(), years = new Set();
  for (const [id, name] of Players) {
    if (id === null || name === null) return 'Every player needs an id and a name.';
    if (ids.has(id)) return `player_id ${id} appears twice in Players.`;
    ids.add(id);
  }
  for (const [year, ...winners] of Championships) {
    if (year === null) return 'Every championship row needs a year.';
    if (years.has(year)) return `year ${year} appears twice in Championships.`;
    years.add(year);
    for (const w of winners) if (!ids.has(w)) return `Winner ${w} in ${year} is not in Players.`;
  }
  return null;
}

