function generate(rand, size) {
  const small = size === 'small';
  const names = ['Nadal', 'Federer', 'Novak', 'Serena', 'Andy', 'Iga', 'Carlos', 'Venus'];
  const playerCount = small ? Math.floor(rand() * 6) : 300;
  const Players = [];
  let id = 0;
  for (let i = 0; i < playerCount; i++) {
    id += 1 + Math.floor(rand() * (small ? 3 : 2));
    Players.push([id, names[Math.floor(rand() * names.length)]]);
  }
  const Championships = [];
  if (Players.length) {
    // Small cases favour a few players so that totals collide and some players win nothing.
    const favourites = small ? Players.slice(0, 1 + Math.floor(rand() * Players.length)) : Players;
    const winner = () => favourites[Math.floor(rand() * favourites.length)][0];
    const years = small ? Math.floor(rand() * 6) : 1500;
    let year = small ? 2015 : 500;
    for (let i = 0; i < years; i++) {
      year += 1 + Math.floor(rand() * 2);
      Championships.push([year, winner(), winner(), winner(), winner()]);
    }
  }
  return [{ Players, Championships }];
}
